import math
from collections import defaultdict

def get_prime_base_and_exponent(N):
    """
    Checks if N is a perfect power of a single prime p, i.e., N = p^a, where a >= 2.
    Returns (p, a) if true, otherwise returns (None, None).
    """
    if N <= 3:
        return (None, None)

    # Trial division to find the smallest prime factor p
    p = -1

    # Check for factor 2
    if N % 2 == 0:
        p = 2
    else:
        # Check for odd factors
        for i in range(3, int(math.sqrt(N)) + 1, 2):
            if N % i == 0:
                p = i
                break

    # If no factor found up to sqrt(N), N itself is prime (exponent 1)
    if p == -1:
        return (None, None) # N is prime, exponent is 1, which is too small

    # Now, check if N is purely a power of p
    exponent = 0
    temp_N = N
    while temp_N > 1:
        if temp_N % p != 0:
            # N has another prime factor besides p
            return (None, None)
        temp_N //= p
        exponent += 1

    # Check the constraint: exponent must be >= 2
    if exponent >= 2:
        return (p, exponent)
    else:
        # Should not happen if N is composite, but safe check
        return (None, None)

# Main search logic
solutions = []
max_sum = 10

# Iterate over all pairs (m, n) such that m + n <= 10 and m, n >= 1
for m in range(1, max_sum):
    for n in range(1, max_sum - m + 1):

        # 1. Calculate the target numbers
        X = m**2 + n
        Y = m + n**2

        # 2. Check if X is a prime power p^a, a >= 2
        p_X, a_X = get_prime_base_and_exponent(X)

        if p_X is None:
            continue

        # 3. Check if Y is a prime power p^b, b >= 2
        p_Y, b_Y = get_prime_base_and_exponent(Y)

        if p_Y is None:
            continue

        # 4. Check if the prime bases are the same
        if p_X == p_Y:
            p = p_X
            solutions.append((m, n, p))

print("Found triples (m, n, p):")
for sol in solutions:
    print(sol)

print("\nTotal solutions found:", len(solutions))
